mapper.select:
SELECT * FROM room_inventory
WHERE type_id = #{typeId}
  AND inv_date >= #{startDate}
  AND inv_date <  #{endDate}
ORDER BY inv_date ASC

mapper.update:
UPDATE room_inventory
SET ordered = ordered + 1,
    version = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND (total - ordered - occupied - reserved - maintenance) >= 1

UPDATE room_inventory
SET ordered = ordered - 1,
    version = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND ordered >= 1

UPDATE room_inventory
SET ordered  = ordered - 1,
    occupied = occupied + 1,
    version  = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND ordered >= 1

UPDATE room_inventory
SET occupied = occupied - 1,
    version  = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND occupied >= 1

UPDATE room_inventory
SET reserved = #{reserved},
    version  = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND #{reserved} >= 0
  AND (total - ordered - occupied - #{reserved} - maintenance) >= 0

UPDATE room_inventory
SET maintenance = #{maintenance},
    version  = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
  AND #{maintenance} >= 0
  AND (total - ordered - occupied - reserved - #{maintenance}) >= 0

UPDATE room_inventory
SET price   = #{price},
    version = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}

UPDATE room_inventory
SET total   = #{total},
    version = version + 1,
    update_time = NOW()
WHERE type_id  = #{typeId}
  AND inv_date = #{invDate}
  AND version  = #{version}
